import { db } from '@/lib/db'
import { getCookie } from '@/lib/cookie'
import { createSlice, createAsyncThunk } from '@reduxjs/toolkit'
import { api } from '@/utils/api'

type Params = { params: Promise<{ id: string }> }

export const updateAdoption = createAsyncThunk(
  'adoption/updateAdoption',
  async (params: Params) => {
    const { id } = await params
    const row = await db.adoption.update({
      where: { id },
      data: { name: String(params?.body?.name ?? '').trim(), age: params?.body?.age },
    })
    if (!row) throw new Error('not found')
    return row
  }
)

export const createAdoption = createAsyncThunk(
  'adoption/createAdoption',
  async (body: { name: string; age: number }) => {
    const row = await db.adoption.create({
      data: { name: body.name, age: body.age },
    })
    return row
  }
)

export const adoptionSlice = createSlice({
  name: 'adoption',
  initialState: { items: [] as Record<string, AdoptionItem>, loading: false },
  reducers: {
    clear: (state) => {
      state.items = []
      state.loading = false
    },
  },
  extraReducers: {
    [updateAdoption.pending]: (state) => {
      state.loading = true
    },
    [updateAdoption.fulfilled]: (state, action) => {
      state.loading = false
      state.items.push(action.payload)
    },
    [updateAdoption.rejected]: (state) => {
      state.loading = false
    },
    [createAdoption.pending]: (state) => {
      state.loading = true
    },
    [createAdoption.fulfilled]: (state, action) => {
      state.loading = false
      state.items.push(action.payload)
    },
    [createAdoption.rejected]: (state) => {
      state.loading = false
    },
  },
})

export type AdoptionState = ReturnType<typeof adoptionSlice.getState>

export const { clear } = adoptionSlice.actions

export const adoptionSelector = (state: AdoptionState) => state.items

export const adoptionApi = api.useGet('/api/adoption/:id', adoptionSelector, {
  staleTime: Infinity,
  enabled: (req, { params }) => Boolean(params?.id),
})

export default adoptionApi
